import json,sys,subprocess,os
d=json.load(sys.stdin)
f=d.get('tool_input',{}).get('file_path','')
if not f.endswith('.js'): sys.exit(0)
if not os.path.isfile(f): sys.exit(0)
content=open(f,'r',encoding='utf-8').read()
r=subprocess.run(['docker','exec','-i','n8n','node','-e','new Function(require(\"fs\").readFileSync(0,\"utf8\"))'],input=content.encode(),capture_output=True,timeout=10)
if r.returncode!=0:
    print(json.dumps({'decision':'block','reason':'Erro sintaxe JS: '+r.stderr.decode().strip()[:200]}))
else:
    print(json.dumps({'systemMessage':'JS OK: '+os.path.basename(f)}))
"

