python -c "
import json,sys,subprocess
try:
    r=subprocess.run(['curl','-s','-o','/dev/null','-w','%{http_code}','http://localhost:8091/health'],capture_output=True,timeout=5)
    code=r.stdout.decode().strip()
    if code=='200':
        print(json.dumps({'systemMessage':'Router health: OK (HTTP '+code+')'}))
    else:
        print(json.dumps({'systemMessage':'ALERTA: Router retornou HTTP '+code}))
except:
    print(json.dumps({'systemMessage':'ALERTA: Router inacessivel!'}))
"
